def transform(grid):
    h, w = len(grid), len(grid[0])

    # The input is a lattice: separator rows/columns carry markers at their
    # intersections. Keep the intersection values, replacing the ordinary
    # lattice color by the interior/background color.
    def dominant(seq):
        return max(set(seq), key=seq.count)

    rstep = 4
    cstep = 8
    rows = list(range(0, h, rstep))
    cols = list(range(0, w, cstep))

    # Ordinary separator color is the most common color on lattice lines;
    # background is the dominant color inside the tiles.
    line_color = dominant(grid[0])
    interior = [
        grid[r][c]
        for r in range(h) for c in range(w)
        if r % rstep not in (0,) and c % cstep not in (0,)
    ]
    background = dominant(interior) if interior else 8

    result = []
    for r in rows[:-1]:
        outrow = []
        for c in cols[:-1]:
            v = grid[r][c]
            outrow.append(background if v == line_color else v)
        result.append(outrow)
    return result
